	}
	if err = insertToolCalls(ctx, tx, row); err != nil {
		return err
	}
	if err = insertFacets(ctx, tx, row); err != nil {
		return err
	}

	if err = tx.Commit(); err != nil {
		return fmt.Errorf("commit transaction: %w", err)
	}
	return nil
}

